window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-16da43cf7f0ebc72"]={"versions": [{"id": "FIG-16da43cf7f0ebc72", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des Einzelschritts „Write DataID“ innerhalb der Funktion <code>E2E_P04Forward()</code> der AUTOSAR E2E-Bibliothek (E2E Profile 4, AUTOSAR_PRS_E2EProtocol). Das Diagramm modelliert die absicherungsbezogene Einfügung der Daten-ID in die Nutzdaten vor dem Weitersenden über eine Gateway- oder Forwarding-Instanz.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Aktivitätskontext / Funktion</strong>: <code>E2E_P04Forward()</code>\n</li><li><strong>Zustands- &amp; Konfigurationsparameter</strong>:\n<ul class=\"fig-list\"><li><code>ForwardStatus</code>: Statusvariable zur Fehlerbewertung, verglichen mit Enumerator <code>E2E_P_ERROR</code>\n</li><li><code>Config-&gt;DataID</code>: 4-Byte-Konfigurationsidentifikator (<code>uint32</code>)\n</li><li><code>Config-&gt;DataID+1</code>: Inkrementierter Datenbezeichner zur gezielten Fehlerübertragung / Ungültigmachung\n</li></ul>\n</li><li><strong>Datenpuffer</strong>:\n<ul class=\"fig-list\"><li>Array bzw. Puffer <code>Data[]</code> mit Byte-Adressierung über <code>Data[Offset+4...Offset+7]</code> in Big-Endian-Byte-Reihenfolge (MSB first)\n</li></ul>\n</li><li><strong>Ablaufknoten</strong>:\n<ul class=\"fig-list\"><li>Initialknoten (Start)\n</li><li>Zwei Verzweigungsknoten (Decision- und Merge-Node als Rauten)\n</li><li>Zwei Aktionsknoten zur Byte-Zuweisung\n</li><li>Aktivitätsendknoten (Stop)\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der Kontrollfluss beginnt am Initialknoten und führt zur ersten Verzweigung mit der Bedingung <code>if ForwardStatus == E2E_P_ERROR</code>.\n</li><li>Evaluierung des Entscheidungsknotens:\n<ul class=\"fig-list\"><li><strong>[TRUE]-Zweig</strong> (Fehlerstatus liegt vor): Ausführung der Aktion „Copy 4-byte Config-&gt;DataID+1 to bytes Data[Offset+4...Offset+7] in Big Endian order“.\n</li><li><strong>[FALSE]-Zweig</strong> (kein Fehlerstatus): Ausführung der Aktion „Copy 4-byte Config-&gt;DataID to bytes Data[Offset+4...Offset+7] in Big Endian order“.\n</li></ul>\n</li><li>Beide Pfade münden in den Merge-Knoten und terminieren am Aktivitätsendknoten.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Der Schritt realisiert eine normative Verhaltensanforderung ([PRS_E2E_00618] gem. RS_E2E_08539) für E2E Profile 4 Forwarding:</p>\n<ul class=\"fig-list\"><li>Im Fehlerfall (<code>ForwardStatus == E2E_P_ERROR</code>) wird absichtlich ein verfälschter DataID-Wert (<code>DataID + 1</code>) in die Bytes <code>[Offset+4 ... Offset+7]</code> geschrieben, sodass nachfolgende E2E-Empfängerprüfungen (<code>E2E_P04Check()</code>) das Paket deterministisch als fehlerhaft verwerfen.\n</li><li>Im regulären Fall (<code>[FALSE]</code>) wird die unveränderte <code>Config-&gt;DataID</code> geschrieben.\n</li><li>Bei der Implementierung ist zwingend auf die netzwerkseitige Byte-Reihenfolge (Big Endian) über die 4 Bytes ab dem berechneten Byte-Offset zu achten.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-c7db01daae5b4997", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des Einzelschritts „Write DataID“ innerhalb der Funktion <code>E2E_P04Forward()</code> der AUTOSAR E2E-Bibliothek (E2E Profile 4, AUTOSAR_PRS_E2EProtocol). Das Diagramm modelliert die absicherungsbezogene Einfügung der Daten-ID in die Nutzdaten vor dem Weitersenden über eine Gateway- oder Forwarding-Instanz.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Aktivitätskontext / Funktion</strong>: <code>E2E_P04Forward()</code>\n</li><li><strong>Zustands- &amp; Konfigurationsparameter</strong>:\n<ul class=\"fig-list\"><li><code>ForwardStatus</code>: Statusvariable zur Fehlerbewertung, verglichen mit Enumerator <code>E2E_P_ERROR</code>\n</li><li><code>Config-&gt;DataID</code>: 4-Byte-Konfigurationsidentifikator (<code>uint32</code>)\n</li><li><code>Config-&gt;DataID+1</code>: Inkrementierter Datenbezeichner zur gezielten Fehlerübertragung / Ungültigmachung\n</li></ul>\n</li><li><strong>Datenpuffer</strong>:\n<ul class=\"fig-list\"><li>Array bzw. Puffer <code>Data[]</code> mit Byte-Adressierung über <code>Data[Offset+4...Offset+7]</code> in Big-Endian-Byte-Reihenfolge (MSB first)\n</li></ul>\n</li><li><strong>Ablaufknoten</strong>:\n<ul class=\"fig-list\"><li>Initialknoten (Start)\n</li><li>Zwei Verzweigungsknoten (Decision- und Merge-Node als Rauten)\n</li><li>Zwei Aktionsknoten zur Byte-Zuweisung\n</li><li>Aktivitätsendknoten (Stop)\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der Kontrollfluss beginnt am Initialknoten und führt zur ersten Verzweigung mit der Bedingung <code>if ForwardStatus == E2E_P_ERROR</code>.\n</li><li>Evaluierung des Entscheidungsknotens:\n<ul class=\"fig-list\"><li><strong>[TRUE]-Zweig</strong> (Fehlerstatus liegt vor): Ausführung der Aktion „Copy 4-byte Config-&gt;DataID+1 to bytes Data[Offset+4...Offset+7] in Big Endian order“.\n</li><li><strong>[FALSE]-Zweig</strong> (kein Fehlerstatus): Ausführung der Aktion „Copy 4-byte Config-&gt;DataID to bytes Data[Offset+4...Offset+7] in Big Endian order“.\n</li></ul>\n</li><li>Beide Pfade münden in den Merge-Knoten und terminieren am Aktivitätsendknoten.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Der Schritt realisiert eine normative Verhaltensanforderung ([PRS_E2E_00618] gem. RS_E2E_08539) für E2E Profile 4 Forwarding:</p>\n<ul class=\"fig-list\"><li>Im Fehlerfall (<code>ForwardStatus == E2E_P_ERROR</code>) wird absichtlich ein verfälschter DataID-Wert (<code>DataID + 1</code>) in die Bytes <code>[Offset+4 ... Offset+7]</code> geschrieben, sodass nachfolgende E2E-Empfängerprüfungen (<code>E2E_P04Check()</code>) das Paket deterministisch als fehlerhaft verwerfen.\n</li><li>Im regulären Fall (<code>[FALSE]</code>) wird die unveränderte <code>Config-&gt;DataID</code> geschrieben.\n</li><li>Bei der Implementierung ist zwingend auf die netzwerkseitige Byte-Reihenfolge (Big Endian) über die 4 Bytes ab dem berechneten Byte-Offset zu achten.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-16da43cf7f0ebc72", "to": "FIG-c7db01daae5b4997", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
